WITH upd AS (
  UPDATE preferences SET is_active = (btrim($2::text) = 'true'), updated_at = now()
  WHERE user_id = $1::uuid AND btrim($2::text) IN ('true', 'false')
  RETURNING is_active
), l AS (INSERT INTO audit_log (event, user_id, details) SELECT 'prefs_active_updated', $1::uuid, '{}'::jsonb FROM upd)
SELECT COALESCE((SELECT to_jsonb(upd) FROM upd), '{"erreur": "aucune modification : valeur invalide ou refusée"}'::jsonb) AS resultat;
